# DK NHV.  Nørresundby S - Nørresundby H
#
let nn = path("d3.dk.nhv");

with detail = 3, railway = :first :nopax :removed {
    # point.dk.Lindholm  dk.FFH

    with link = "line.dk.NHV", railway = :station {
        track(
                nn[:lin.ys - 1.1dl, :lin.ys - 1dl]
            --  nn[:lin.ys, :noh.yl] << 1ms << 1mt
        );
        track(nn[:noh.yl, :noh - 0.49sw] << 1ms << 1mt);
    }

    # point.dk.Nørresundby-H  # dk.NFH
}

